      c = v[(e + 1) % 4];
      k = edgeKey(a, c);
      if (!edgeMap.has(k)) edgeMap.set(k, []);
      edgeMap.get(k).push(q);
    }
  }

  var neighbors = [];
  for (q = 0; q < quadCount; q++) {
    neighbors.push([]);
  }
  edgeMap.forEach(function (quads) {
    if (quads.length === 2) {
      var q0 = quads[0];
      var q1 = quads[1];
      neighbors[q0].push(q1);
      neighbors[q1].push(q0);
    }
  });

  return neighbors;
};


function rotateVectorRodrigues(v, k, angle) {
  var c = Math.cos(angle);
  var s = Math.sin(angle);
  var kdotv = v.x * k.x + v.y * k.y + v.z * k.z;
  var cx = k.y * v.z - k.z * v.y;
  var cy = k.z * v.x - k.x * v.z;
  var cz = k.x * v.y - k.y * v.x;
  var om = 1 - c;
  return {
    x: v.x * c + cx * s + k.x * kdotv * om,
    y: v.y * c + cy * s + k.y * kdotv * om,
    z: v.z * c + cz * s + k.z * kdotv * om,
  };
}

function rotatePointAroundDiagonal(A, P, C, angle) {
  var dx = C.x - A.x;
  var dy = C.y - A.y;
  var dz = (C.z || 0) - (A.z || 0);
  var len = Math.hypot(dx, dy, dz) || 1e-9;
  var k = { x: dx / len, y: dy / len, z: dz / len };
  var v = {
    x: P.x - A.x,
    y: P.y - A.y,
    z: (P.z || 0) - (A.z || 0),
  };
  var r = rotateVectorRodrigues(v, k, angle);
  return {
    x: A.x + r.x,
    y: A.y + r.y,
    z: (A.z || 0) + r.z,
  };
}

TS.projectWeakPerspective = function (P, eyeZ) {
  var z = P.z || 0;
  var denom = eyeZ - z;
  var f = eyeZ / (Math.abs(denom) < 1e-9 ? 1e-9 : denom);
  return { x: P.x * f, y: P.y * f };
};

/**
 * @param t - 0..1 → angle 0..2π
 */
TS.getFlippedQuadCorners2D = function (
  vertices,
  i0,
  i1,
  i2,
  i3,
  diagonal,
  t,
  eyeZ
) {
  function P(i) {
    return {
      x: vertices[i].x,
      y: vertices[i].y,
      z: vertices[i].z || 0,
    };
  }

  var angle = t * Math.PI * 2;

  var v0;
  var v1;
  var v2;
  var v3;
  if (diagonal === 0) {
    v0 = P(i0);
    v1 = P(i1);
    v2 = P(i2);
    v3 = P(i3);
    var v1r = rotatePointAroundDiagonal(v0, v1, v2, angle);
    var v3r = rotatePointAroundDiagonal(v0, v3, v2, angle);
    return [
      TS.projectWeakPerspective(v0, eyeZ),
      TS.projectWeakPerspective(v1r, eyeZ),
      TS.projectWeakPerspective(v2, eyeZ),
      TS.projectWeakPerspective(v3r, eyeZ),
    ];
  }

  v0 = P(i0);
  v1 = P(i1);
  v2 = P(i2);
  v3 = P(i3);
  var v0r = rotatePointAroundDiagonal(v1, v0, v3, angle);
  var v2r = rotatePointAroundDiagonal(v1, v2, v3, angle);
  return [
    TS.projectWeakPerspective(v0r, eyeZ),
    TS.projectWeakPerspective(v1, eyeZ),
    TS.projectWeakPerspective(v2r, eyeZ),
    TS.projectWeakPerspective(v3, eyeZ),
  ];
};

// ----- Color helpers -----
TS.pingPongIndex = function (i, length) {
  if (length <= 1) return 0;
  var period = 2 * (length - 1);
  var pos = ((i % period) + period) % period;
  return pos < length ? pos : period - pos;
};

TS.hexToRgb = function (hex) {
  var h = hex.replace("#", "").trim();
  var n =
    h.length === 3
      ? h
          .split("")
          .map(function (c) {
            return c + c;
          })
          .join("")
      : h;
  return [
    parseInt(n.slice(0, 2), 16),
    parseInt(n.slice(2, 4), 16),
    parseInt(n.slice(4, 6), 16),
  ];
};


// === Tab: mySketch ===
// Patchwork
// I saw this library called Sylves for working with grids, and reimplemented the "townscaper grid" in JS (https://www.boristhebrave.com/docs/sylves/1/articles/tutorials/townscaper.html)
// Grid code is mostly adapted from the C# version, is not very javascript
// The sketch has some "walkers" that randomly traverse the grid and color the tiles underneath, with a simple "flip" animation

/**
 * Settings:
 * - n: chunk radius (1–16)
 * - seed: mesh + default walk RNG
 * - relax: Laplacian smoothing iterations (0 = ortho+weld only)
 * - wire: wireframe only
 * - linePx: stroke width in screen pixels
 * - pad: inner margin from canvas edge
 * - snakes: competing snake walkers
 * - stepsPerFrame: moves per snake per frame
 * - walkSeed: RNG seed for snakes / flips (set equal to seed if you want them tied)
 * - noWalk: static paper fill, no snakes
 * - noflip: claim tiles instantly (no flip animation)
 * - flipFrames: nominal frames per full 360° flip (for your own reference)
 * - flipSpeed: progress per frame toward 1 (e.g. 1/60 matches flipFrames 60)
 * - eye: perspective distance for flip; 0 = auto from mesh bounds (uses Math.max)
 */
var CONFIG = {
  n: 10,
  seed: 42,
  relax: 12,
  tolerance: 0.01,
  wire: false,
  linePx: 1.25,
  pad: 4,
  stepsPerFrame: 1,
  walkSeed: 42,
  noWalk: false,
  noflip: false,
  flipFrames: 60,
  flipSpeed: 1 / 60,
  eye: 0,
  snakes: 6,
};

var palettes = [
  ["#cce5ff", "#99ccff", "#66b2ff", "#3299ff", "#007fff", "#0066cc", "#004c99", "#003366", "#001933"],
  ["#daf2da", "#b8e6b8", "#98d998", "#7acc7a", "#60bf60", "#47b347", "#32a632", "#1f991f", "#118c11", "#008000"],
  ["#ffe169", "#fad643", "#edc531", "#dbb42c", "#c9a227", "#b69121", "#ad881e", "#a47e1b", "#926c15", "#805b10"],
  ["#aa0000", "#bb0000", "#cd0000", "#de1616", "#ef2b2b", "#ec4040", "#e95555", "#e56b6b", "#e28080", "#eaa8a8"],
];

var mesh;
var b;
var bwMesh;
var bhMesh;
var eyeZ;
var neighbors;
var quadCount;

var C_FILL = [244, 244, 241];
var C_STROKE = [51, 51, 51];

var snakePassCount;
var tileR;
var tileG;
var tileB;
var qi;

var flipProgress;
var flipDiagonal;
var pendingSnake;

var snakeRng;
var flipPickRng;
var snakeQuad;

function setup() {
  mesh = TS.buildTownscaperChunk(
    CONFIG.n,
    CONFIG.seed,
    CONFIG.tolerance,
    CONFIG.relax
  );
  b = bounds2d(mesh.vertices);
  bwMesh = b.maxX - b.minX;
  bhMesh = b.maxY - b.minY;
  eyeZ =
    CONFIG.eye > 0
      ? CONFIG.eye
      : Math.max(5, Math.max(bwMesh, bhMesh) * 2.5);
  neighbors = TS.buildQuadAdjacency(mesh);
  quadCount = mesh.indices.length / 4;
  shuffle(palettes, true)

  snakePassCount = new Int32Array(Math.max(1, CONFIG.snakes));

  tileR = new Uint8Array(quadCount);
  tileG = new Uint8Array(quadCount);
  tileB = new Uint8Array(quadCount);
  for (qi = 0; qi < quadCount; qi++) {
    tileR[qi] = 255;
    tileG[qi] = 255;
    tileB[qi] = 255;
  }

  flipProgress = new Float32Array(quadCount);
  flipProgress.fill(1);
  flipDiagonal = new Uint8Array(quadCount);
  pendingSnake = new Int16Array(quadCount);
  pendingSnake.fill(-1);

  snakeRng = [];
  var s;
  for (s = 0; s < CONFIG.snakes; s++) {
    snakeRng.push(TS.mulberry32((CONFIG.walkSeed + s * 0x1a2b3c4d) >>> 0));
  }
  flipPickRng = TS.mulberry32((CONFIG.walkSeed ^ 0x9e3779b9) >>> 0);

  snakeQuad = new Int32Array(CONFIG.snakes);

  createCanvas(
    windowWidth > 0 ? windowWidth : 720,
    windowHeight > 0 ? windowHeight : 720
  );
  strokeJoin(ROUND);
  if (!CONFIG.wire && !CONFIG.noWalk) {
    initSnakePositions();
    for (s = 0; s < CONFIG.snakes; s++) {
      startFlip(snakeQuad[s], s);
    }
  }
}

function draw() {
  background(0);

  if (!CONFIG.wire && !CONFIG.noWalk) {
    stepSnakes(CONFIG.stepsPerFrame);
    advanceFlips();
  }

  var pad = CONFIG.pad;
  var cw = width - 2 * pad;
  var ch = height - 2 * pad;
  var bw = bwMesh;
  var bh = bhMesh;
  var _scale = Math.min(cw / bw, ch / bh);
  var cx = (b.minX + b.maxX) / 2;
  var cy = (b.minY + b.maxY) / 2;

  push();
  translate(width / 2, height / 2);
  scale(_scale, -_scale);
  translate(-cx, -cy);
  strokeWeight(CONFIG.linePx / _scale);

  if (CONFIG.wire) {
    noFill();
    stroke(210, 218, 235);
  } else if (CONFIG.noWalk) {
    fill(C_FILL[0], C_FILL[1], C_FILL[2]);
    stroke(C_STROKE[0], C_STROKE[1], C_STROKE[2]);
  } else {
    stroke(C_STROKE[0], C_STROKE[1], C_STROKE[2]);
  }

  var vertices = mesh.vertices;
  var indices = mesh.indices;
  var i0;
  var i1;
  var i2;
  var i3;
  var v0;
  var v1;
  var v2;
  var v3;
  var useFlip;
  var tFlip;
  var corners;
  var i;
  for (qi = 0, i = 0; i < indices.length; qi++, i += 4) {
    if (!CONFIG.wire && !CONFIG.noWalk) {
      fill(tileR[qi], tileG[qi], tileB[qi]);
    }

    i0 = indices[i];
    i1 = indices[i + 1];
    i2 = indices[i + 2];
    i3 = indices[i + 3];
    v0 = vertices[i0];
    v1 = vertices[i1];
    v2 = vertices[i2];
    v3 = vertices[i3];

    useFlip =
      !CONFIG.wire &&
      !CONFIG.noWalk &&
      !CONFIG.noflip &&
      flipProgress[qi] >= 0 &&
      flipProgress[qi] < 0.999;

    if (useFlip) {
      tFlip = flipProgress[qi];
      corners = TS.getFlippedQuadCorners2D(
        vertices,
        i0,
        i1,
        i2,
        i3,
        flipDiagonal[qi],
        tFlip,
        eyeZ
      );
      quad(
        corners[0].x,
        corners[0].y,
        corners[1].x,
        corners[1].y,
        corners[2].x,
        corners[2].y,
        corners[3].x,
        corners[3].y
      );
    } else {
      quad(v0.x, v0.y, v1.x, v1.y, v2.x, v2.y, v3.x, v3.y);
    }
  }
  pop();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function bounds2d(vertices) {
  var minX = Infinity;
  var maxX = -Infinity;
  var minY = Infinity;
  var maxY = -Infinity;
  var i;
  var v;
  for (i = 0; i < vertices.length; i++) {
    v = vertices[i];
    minX = Math.min(minX, v.x);
    maxX = Math.max(maxX, v.x);
    minY = Math.min(minY, v.y);
    maxY = Math.max(maxY, v.y);
  }
  return { minX: minX, maxX: maxX, minY: minY, maxY: maxY };
}

function snakePalette(snakeId) {
  return palettes[snakeId % palettes.length];
}

function nextColorForSnake(snakeId) {
  var row = snakePalette(snakeId);
  var idx = TS.pingPongIndex(snakePassCount[snakeId], row.length);
  snakePassCount[snakeId]++;
  return TS.hexToRgb(row[idx]);
}

function initSnakePositions() {
  var used = new Set();
  var s;
  var q;
  var guard;
  for (s = 0; s < CONFIG.snakes; s++) {
    guard = 0;
    do {
      q = (snakeRng[s]() * quadCount) | 0;
      guard++;
    } while (used.has(q) && guard < quadCount * 4);
    used.add(q);
    snakeQuad[s] = q;
  }
}

function startFlip(qi, snakeId) {
  pendingSnake[qi] = snakeId;
  var rgb = nextColorForSnake(snakeId);
  tileR[qi] = rgb[0];
  tileG[qi] = rgb[1];
  tileB[qi] = rgb[2];
  if (CONFIG.noflip) {
    flipProgress[qi] = 1;
    pendingSnake[qi] = -1;
    return;
  }
  flipProgress[qi] = 0;
  flipDiagonal[qi] = flipPickRng() < 0.5 ? 0 : 1;
}

function stepSnakesOnce() {
  var s;
  var cur;
  var nbs;
  var nxt;
  for (s = 0; s < CONFIG.snakes; s++) {
    cur = snakeQuad[s];
    nbs = neighbors[cur];
    if (nbs.length === 0) continue;
    nxt = nbs[(snakeRng[s]() * nbs.length) | 0];
    snakeQuad[s] = nxt;
    startFlip(nxt, s);
  }
}

function stepSnakes(steps) {
  var t;
  for (t = 0; t < steps; t++) {
    stepSnakesOnce();
  }
}

function advanceFlips() {
  if (CONFIG.noflip) return;
  var spd = CONFIG.flipSpeed;
  var prev;
  var next;
  for (qi = 0; qi < quadCount; qi++) {
    if (flipProgress[qi] >= 1) continue;
    prev = flipProgress[qi];
    next = Math.min(1, prev + spd);
    flipProgress[qi] = next;
    if (prev < 1 && next >= 1) {
      pendingSnake[qi] = -1;
    }
  }
}


